/* ham-home-card: whole-apartment floor plan with live device state (DRAFT).
 *
 * Also defines ham-proposed-card, a compact dashed "Proposed, not created yet" card.
 * Single file, no build, no network requests. Both elements read everything from their
 * config; ham-home-card also reads hass.states. It never calls a service.
 *
 * Config (normally generated by build.py, see dashboard.json):
 *   type: custom:ham-home-card
 *   layout: auto | portrait | landscape   # auto = landscape when the card is >= 560 px wide
 *   room: living_room                     # optional preselected room key
 *   rooms:  [{key, name, short, corners:[[x,y]..], occ:'input_boolean.x_occupied', placeholder,
 *             devices:[{id, kind, name, entity, x, y, facing}], fixtures:[{name, points}]}]
 *   doorways: [{name, kind:'door'|'opening', points:[[x,y],[x,y]], exterior}]
 *
 * Coordinates are apartment inches: x grows south, y grows west. Portrait draws
 * screen_x = x, screen_y = y (east is up). Landscape rotates that 90 degrees clockwise
 * (north up, east right) so the long apartment fits a wide screen.
 *
 * Events: tapping a device fires hass-more-info {entityId}; tapping a room (or a chip)
 * fires ham-room-select {room: key|null} and zooms to / highlights that room.
 */
(() => {
  const C = {
    light: '#ffc857', motion: '#6cb0ff', contact: '#ff9f43', fan: '#7bd88f',
    camera: '#c792ea', dead: '#7a8590', warn: '#ff9f43',
  };
  const BAD = ['unavailable', 'unknown', undefined];
  const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;');
  const num = (v) => Math.round(v * 100) / 100;

  class HamHomeCard extends HTMLElement {
    constructor() {
      super();
      this.attachShadow({ mode: 'open' });
      this._sel = null;
      this._sig = '';
      this._w = 0;
      this.shadowRoot.addEventListener('click', (e) => this._click(e));
    }

    setConfig(config) {
      if (!config || !Array.isArray(config.rooms) || !config.rooms.length) {
        throw new Error('ham-home-card: "rooms" is required');
      }
      this._c = config;
      this._sel = config.room || null;
      this._sig = '';
      this._ents = [];
      config.rooms.forEach((r) => {
        if (r.occ) this._ents.push(r.occ);
        (r.devices || []).forEach((d) => d.entity && this._ents.push(d.entity));
      });
      this._render();
    }

    set hass(h) {
      this._hass = h;
      const sig = this._signature();
      if (sig !== this._sig) {
        this._sig = sig;
        this._render();
      }
    }

    getCardSize() { return 12; }

    connectedCallback() {
      if (typeof ResizeObserver === 'undefined') return;
      this._ro = new ResizeObserver(() => {
        const w = Math.round(this.clientWidth);
        if (w && Math.abs(w - this._w) > 2) this._render();
      });
      this._ro.observe(this);
    }

    disconnectedCallback() { if (this._ro) this._ro.disconnect(); }

    _signature() {
      const s = this._hass && this._hass.states;
      if (!s || !this._ents) return '';
      return this._ents.map((e) => {
        const o = s[e];
        return o ? o.state + (o.attributes && o.attributes.brightness != null ? ':' + o.attributes.brightness : '') : '-';
      }).join('|');
    }

    _st(ent) { return this._hass && this._hass.states ? this._hass.states[ent] : undefined; }

    _click(e) {
      const dev = e.target.closest('[data-ent]');
      if (dev) {
        this.dispatchEvent(new CustomEvent('hass-more-info', {
          detail: { entityId: dev.dataset.ent }, bubbles: true, composed: true,
        }));
        return;
      }
      const el = e.target.closest('[data-room]');
      if (el) {
        const key = el.dataset.room || null;
        this._sel = key && key === this._sel ? null : key;
        this.dispatchEvent(new CustomEvent('ham-room-select', {
          detail: { room: this._sel }, bubbles: true, composed: true,
        }));
        this._render();
        return;
      }
      if (e.target.closest('svg')) { // background tap clears the selection
        if (this._sel) {
          this._sel = null;
          this.dispatchEvent(new CustomEvent('ham-room-select', { detail: { room: null }, bubbles: true, composed: true }));
          this._render();
        }
      }
    }

    // ---- device appearance from live state -------------------------------------------
    _look(d) {
      const o = this._st(d.entity);
      const st = o ? o.state : undefined;
      const dead = BAD.includes(st);
      const on = st === 'on';
      const k = d.kind;
      if (dead) return { col: C.dead, op: 0.55, fill: 0, dead: true, on: false, txt: st || 'not in HA' };
      if (k === 'light') {
        const b = o.attributes && o.attributes.brightness != null ? o.attributes.brightness / 255 : 1;
        return { col: C.light, op: on ? 0.4 + 0.6 * b : 1, fill: on ? 1 : 0, on, txt: on ? 'on ' + Math.round(b * 100) + '%' : 'off' };
      }
      if (k === 'contact') return { col: on ? C.contact : '#8fa3b5', op: 1, fill: on ? 1 : 0, on, txt: on ? 'open' : 'closed' };
      if (k === 'fan') return { col: C.fan, op: 1, fill: on ? 1 : 0, on, txt: st };
      if (k === 'camera') return { col: C.camera, op: 1, fill: on ? 1 : 0, on, txt: on ? 'motion' : 'quiet' };
      if (k === 'button') return { col: '#8fa3b5', op: 1, fill: 0, on: false, txt: 'button' };
      return { col: C.motion, op: 1, fill: on ? 1 : 0, on, txt: on ? 'active' : 'clear' }; // motion, radar, other
    }

    _glyph(d, L) {
      const col = L.col;
      const f = L.fill ? col : 'none';
      const sw = 1.8;
      const base = `fill="var(--card-background-color,#171c23)" stroke="none"`;
      let g = `<circle r="11" ${base} opacity=".85"/>`;
      const a = `stroke="${col}" stroke-width="${sw}" stroke-linecap="round" stroke-linejoin="round"`;
      switch (d.kind) {
        case 'light':
          g += `<circle r="6.5" fill="${f}" fill-opacity="${num(L.op)}" ${a}/>`;
          if (L.on) g += `<circle r="10" fill="none" stroke="${col}" stroke-opacity="${num(L.op * 0.5)}" stroke-width="1.5"/>`;
          break;
        case 'motion':
          g += `<circle r="2.6" fill="${col}"/><path d="M-6.5 -2.5 A7 7 0 0 1 -2.5 -6.5 M6.5 -2.5 A7 7 0 0 0 2.5 -6.5" fill="none" ${a}/>` +
            `<circle r="9.5" fill="${L.on ? col : 'none'}" fill-opacity=".25" stroke="${col}" stroke-width="1.4"/>`;
          break;
        case 'radar':
          g += `<path d="M0 -7 L7 0 L0 7 L-7 0 Z" fill="${f}" fill-opacity=".55" ${a}/><circle r="1.8" fill="${col}"/>`;
          break;
        case 'button':
          g += `<rect x="-6" y="-6" width="12" height="12" rx="3.5" fill="none" ${a}/><circle r="2.2" fill="${col}"/>`;
          break;
        case 'contact':
          g += `<rect x="-6.5" y="-5.5" width="5.5" height="11" rx="1" fill="${f}" fill-opacity=".6" ${a}/>` +
            `<rect x="${L.on ? 1.5 : 1}" y="-5.5" width="5.5" height="11" rx="1" fill="${f}" fill-opacity=".3" ${a} transform="${L.on ? 'rotate(18 6 0)' : ''}"/>`;
          break;
        case 'fan':
          g += `<g fill="${f}" fill-opacity=".5" ${a}><ellipse cx="0" cy="-4.2" rx="2.6" ry="4"/><ellipse cx="0" cy="4.2" rx="2.6" ry="4"/>` +
            `<ellipse cx="-4.2" cy="0" rx="4" ry="2.6"/><ellipse cx="4.2" cy="0" rx="4" ry="2.6"/></g>`;
          break;
        case 'camera':
          g += `<rect x="-7" y="-4.5" width="10" height="9" rx="2" fill="${f}" fill-opacity=".5" ${a}/><path d="M3 -1.5 L7.5 -4 V4 L3 1.5Z" fill="${col}"/>`;
          break;
        default:
          g += `<circle r="5" fill="${f}" ${a}/>`;
      }
      if (L.dead) g += `<path d="M-8 8 L8 -8" stroke="${C.dead}" stroke-width="1.6"/>`;
      return `<g opacity="${L.dead ? 0.7 : 1}">${g}</g>`;
    }

    // Pick the point inside the room whose label box stays furthest from device icons.
    _labelSpot(cp, hw, hh, devs, scale, cx0, cy0) {
      const xs = cp.map((p) => p[0]), ys = cp.map((p) => p[1]);
      const minx = Math.min(...xs), maxx = Math.max(...xs), miny = Math.min(...ys), maxy = Math.max(...ys);
      const inside = (x, y) => {
        let c = false;
        for (let i = 0, j = cp.length - 1; i < cp.length; j = i++) {
          const a = cp[i], b = cp[j];
          if ((a[1] > y) !== (b[1] > y) && x < ((b[0] - a[0]) * (y - a[1])) / (b[1] - a[1]) + a[0]) c = !c;
        }
        return c;
      };
      let best = [cx0, cy0], bs = -Infinity;
      const N = 14;
      for (let i = 0; i <= N; i++) {
        for (let j = 0; j <= N; j++) {
          const x = minx + ((maxx - minx) * i) / N, y = miny + ((maxy - miny) * j) / N;
          if (![[x - hw, y - hh], [x + hw, y - hh], [x - hw, y + hh], [x + hw, y + hh]].every((q) => inside(q[0], q[1]))) continue;
          let m = 60;
          devs.forEach((d) => {
            const dx = Math.max(0, Math.abs(d.sx - x) - hw), dy = Math.max(0, Math.abs(d.sy - y) - hh);
            m = Math.min(m, Math.hypot(dx, dy) * scale);
          });
          const sc = Math.min(m, 24) - Math.hypot(x - cx0, y - cy0) * scale * 0.02;
          if (sc > bs) { bs = sc; best = [x, y]; }
        }
      }
      return best;
    }

    // ---- main render -----------------------------------------------------------------
    _render() {
      if (!this._c) return;
      const c = this._c;
      const W = Math.round(this.clientWidth) || Math.round(this.getBoundingClientRect().width) || 360;
      this._w = W;
      const mode = c.layout === 'portrait' || c.layout === 'landscape' ? c.layout : (W >= 560 ? 'landscape' : 'portrait');
      const tf = mode === 'portrait' ? (x, y) => [x, y] : (x, y) => [-y, x];
      const rot = mode === 'portrait' ? 0 : 90;
      const rooms = c.rooms;
      const sel = rooms.find((r) => r.key === this._sel) || null;

      // view box: whole plan, or the selected room (zoom)
      const pts = (sel ? [sel] : rooms).flatMap((r) => r.corners.map((p) => tf(p[0], p[1])));
      let x0 = Math.min(...pts.map((p) => p[0])), x1 = Math.max(...pts.map((p) => p[0]));
      let y0 = Math.min(...pts.map((p) => p[1])), y1 = Math.max(...pts.map((p) => p[1]));
      const pad = sel ? 22 : 14;
      x0 -= pad; y0 -= pad; x1 += pad; y1 += pad;
      const vbW = x1 - x0, vbH = y1 - y0;
      const maxH = sel ? 720 : (c.max_height || 1100);
      const scale = Math.min(W / vbW, maxH / vbH); // screen px per inch
      const px = (v) => v / scale; // px -> user units
      const sw = num(vbW * scale), sh = num(vbH * scale);

      const poly = (corners) => corners.map((p) => tf(p[0], p[1]).map(num).join(',')).join(' ');

      // devices in screen px space, for hit-target sizing
      const devs = [];
      rooms.forEach((r) => (r.devices || []).forEach((d) => {
        if (!d.entity) return;
        const [sx, sy] = tf(d.x, d.y);
        devs.push({ d, r, sx, sy });
      }));
      devs.forEach((a) => {
        let best = Infinity;
        devs.forEach((b) => {
          if (a !== b) best = Math.min(best, Math.hypot((a.sx - b.sx) * scale, (a.sy - b.sy) * scale));
        });
        a.hit = Math.max(9, Math.min(18, best / 2));
        a.gs = best >= 26 ? 1 : Math.max(0.6, best / 26); // shrink icons in tight clusters
      });

      let svg = '';
      // 1. room fills
      rooms.forEach((r) => {
        const o = r.occ ? this._st(r.occ) : null;
        const occupied = o && (o.state === 'on' || o.state === 'occupied');
        const isSel = sel && sel.key === r.key;
        svg += `<g data-room="${esc(r.key)}" style="cursor:pointer">`;
        svg += `<polygon points="${poly(r.corners)}" fill="var(--secondary-background-color,#222a33)"/>`;
        if (occupied) svg += `<polygon points="${poly(r.corners)}" fill="var(--primary-color,#03a9f4)" fill-opacity=".30"/>`;
        svg += `<polygon points="${poly(r.corners)}" fill="none" stroke="${isSel ? 'var(--primary-color,#03a9f4)' : 'var(--divider-color,#3a4552)'}" ` +
          `stroke-width="${num(px(isSel ? 3.2 : 2))}" ${r.placeholder ? `stroke-dasharray="${num(px(5))} ${num(px(4))}"` : ''} stroke-linejoin="round"/>`;
        svg += `<title>${esc(r.name)}${o ? ' (' + (occupied ? 'occupied' : 'vacant') + ')' : ''}</title></g>`;
      });
      // 2. fixtures
      rooms.forEach((r) => (r.fixtures || []).forEach((f) => {
        svg += `<polygon points="${poly(f.points)}" fill="none" stroke="var(--secondary-text-color,#9aa7b4)" stroke-opacity=".45" ` +
          `stroke-width="${num(px(1))}" stroke-dasharray="${num(px(3))} ${num(px(2))}" pointer-events="none"/>`;
      }));
      // 3. doorways: erase the wall and mark the ends
      (c.doorways || []).forEach((d) => {
        const [a, b] = d.points.map((p) => tf(p[0], p[1]));
        const ln = (col, w, extra) => `<line x1="${num(a[0])}" y1="${num(a[1])}" x2="${num(b[0])}" y2="${num(b[1])}" stroke="${col}" stroke-width="${num(px(w))}" ${extra || ''} pointer-events="none"/>`;
        svg += ln('var(--card-background-color,#171c23)', 6);
        if (d.exterior) svg += ln(C.warn, 3, `stroke-linecap="butt" stroke-opacity=".9"`);
        else if (d.kind === 'door') svg += ln('var(--secondary-text-color,#9aa7b4)', 1.2, `stroke-dasharray="${num(px(3))} ${num(px(3))}" stroke-opacity=".7"`);
        [a, b].forEach((p) => { svg += `<circle cx="${num(p[0])}" cy="${num(p[1])}" r="${num(px(1.6))}" fill="var(--divider-color,#3a4552)" pointer-events="none"/>`; });
      });
      // 4. room labels
      rooms.forEach((r) => {
        const cp = r.corners.map((p) => tf(p[0], p[1]));
        const minx = Math.min(...cp.map((p) => p[0])), maxx = Math.max(...cp.map((p) => p[0]));
        const miny = Math.min(...cp.map((p) => p[1])), maxy = Math.max(...cp.map((p) => p[1]));
        const wpx = (maxx - minx) * scale;
        let cx = (minx + maxx) / 2, cy = (miny + maxy) / 2;
        const full = wpx < 70 && r.short ? r.short : r.name;
        const fs = wpx < 60 ? 9.5 : 12;
        let lines = [full];
        if (full.length * fs * 0.58 > wpx - 6 && full.includes(' ')) lines = full.split(' ');
        const hw = (Math.max(...lines.map((t) => t.length)) * fs * 0.3 + 3) / scale, hh = ((lines.length * (fs + 1)) / 2 + 2) / scale;
        const best = this._labelSpot(cp, hw, hh, devs, scale, cx, cy);
        cx = best[0]; cy = best[1];
        const lh = px(fs + 1);
        const y = cy - ((lines.length - 1) * lh) / 2;
        const opacity = sel && sel.key !== r.key ? 0.45 : 1;
        svg += `<text text-anchor="middle" font-size="${num(px(fs))}" font-weight="600" fill="var(--primary-text-color,#e8edf2)" opacity="${opacity}" ` +
          `stroke="var(--card-background-color,#171c23)" stroke-width="${num(px(3))}" paint-order="stroke" pointer-events="none" font-family="inherit">` +
          lines.map((t, i) => `<tspan x="${num(cx)}" y="${num(y + i * lh + px(fs * 0.35))}">${esc(t)}</tspan>`).join('') + '</text>';
      });
      // 5. facing cones under the icons
      devs.forEach(({ d, sx, sy }) => {
        if ((d.kind !== 'motion' && d.kind !== 'radar') || d.facing == null) return;
        const g = ((d.facing + rot) * Math.PI) / 180, half = (28 * Math.PI) / 180, len = px(26);
        const p = (ang) => `${num(sx + Math.sin(ang) * len)},${num(sy - Math.cos(ang) * len)}`;
        const L = this._look(d);
        svg += `<path d="M${num(sx)},${num(sy)} L${p(g - half)} L${p(g + half)} Z" fill="${C.motion}" fill-opacity="${L.on ? 0.3 : 0.1}" pointer-events="none"/>`;
      });
      // 6. device icons + invisible hit circles
      devs.forEach(({ d, sx, sy, hit, gs }) => {
        const L = this._look(d);
        svg += `<g data-ent="${esc(d.entity)}" transform="translate(${num(sx)} ${num(sy)}) scale(${num(1 / scale)})" style="cursor:pointer">` +
          `<title>${esc(d.name)}: ${esc(L.txt)}</title>` +
          `<g transform="scale(${num(gs)})">${this._glyph(d, L)}</g>` + `<circle r="${num(hit)}" fill="transparent"/></g>`;
      });

      const chips = [`<button data-room="" class="chip ${sel ? '' : 'on'}">All</button>`]
        .concat(rooms.map((r) => `<button data-room="${esc(r.key)}" class="chip ${sel && sel.key === r.key ? 'on' : ''}">${esc(r.short || r.name)}</button>`)).join('');
      // chip with data-room="" must clear: _click maps '' to null already.

      this.shadowRoot.innerHTML = `
        <style>
          :host { display: block; }
          ha-card { display: block; padding: 8px 0 10px; overflow: hidden; }
          .chips { display: flex; gap: 6px; overflow-x: auto; padding: 0 12px 8px; scrollbar-width: none; }
          .chips::-webkit-scrollbar { display: none; }
          .chip { flex: 0 0 auto; min-height: 36px; padding: 0 14px; border-radius: 18px; cursor: pointer;
            border: 1px solid var(--divider-color,#3a4552); background: transparent; color: var(--primary-text-color,#e8edf2); font: inherit; font-size: 13px; }
          .chip.on { background: var(--primary-color,#03a9f4); border-color: var(--primary-color,#03a9f4); color: var(--text-primary-color,#fff); }
          svg { display: block; margin: 0 auto; max-width: 100%; height: auto; touch-action: manipulation; -webkit-tap-highlight-color: transparent; }
          .key { display: flex; flex-wrap: wrap; gap: 4px 14px; padding: 6px 14px 0; font-size: 12px; color: var(--secondary-text-color,#9aa7b4); }
          .key i { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: 5px; vertical-align: -1px; }
        </style>
        <ha-card>
          <div class="chips">${chips}</div>
          <svg viewBox="${num(x0)} ${num(y0)} ${num(vbW)} ${num(vbH)}" width="${sw}" height="${sh}" role="img" aria-label="Apartment floor plan">${svg}</svg>
          <div class="key"><span><i style="background:${C.light}"></i>light on</span><span><i style="background:${C.motion}"></i>motion</span>` +
          `<span><i style="background:${C.contact}"></i>open</span><span><i style="background:${C.dead}"></i>unavailable</span>` +
          `<span><i style="background:var(--primary-color,#03a9f4);opacity:.5"></i>room occupied</span></div>
        </ha-card>`;
    }
  }

  // ---- ham-proposed-card: dashed, collapsed list of helpers that do not exist yet -------
  class HamProposedCard extends HTMLElement {
    constructor() { super(); this.attachShadow({ mode: 'open' }); }
    setConfig(config) {
      if (!config || !Array.isArray(config.items)) throw new Error('ham-proposed-card: "items" is required');
      this._c = config;
      const n = config.items.length;
      const rows = config.items.map((i) => `
        <li><b>${esc(i.name)}</b> <span class="scope">${esc(i.scope || config.scope || '')}</span>
          <code>${esc(i.entity)}</code>${i.note ? `<div class="note">${esc(i.note)}</div>` : ''}</li>`).join('');
      this.shadowRoot.innerHTML = `
        <style>
          :host { display: block; }
          ha-card { display: block; border: 2px dashed var(--divider-color,#5b6773); background: transparent; box-shadow: none; }
          details { padding: 2px 14px; }
          summary { cursor: pointer; min-height: 44px; display: flex; align-items: center; gap: 8px; color: var(--secondary-text-color,#9aa7b4); font-size: 14px; list-style: none; }
          summary::-webkit-details-marker { display: none; }
          summary::before { content: '\\25B8'; }
          details[open] summary::before { content: '\\25BE'; }
          .tag { margin-left: auto; font-size: 11px; text-transform: uppercase; letter-spacing: .06em; color: var(--warning-color,#ff9f43); }
          ul { margin: 0 0 10px; padding: 0; list-style: none; }
          li { padding: 8px 0; border-top: 1px dashed var(--divider-color,#3a4552); font-size: 14px; color: var(--primary-text-color,#e8edf2); }
          code { display: block; font-size: 12px; color: var(--secondary-text-color,#9aa7b4); word-break: break-all; }
          .scope { font-size: 11px; color: var(--secondary-text-color,#9aa7b4); border: 1px solid var(--divider-color,#3a4552); border-radius: 8px; padding: 0 6px; margin-left: 4px; }
          .note { font-size: 12px; color: var(--secondary-text-color,#9aa7b4); margin-top: 2px; }
          .lead { font-size: 12px; color: var(--secondary-text-color,#9aa7b4); padding: 0 0 6px; }
        </style>
        <ha-card><details ${config.open ? 'open' : ''}>
          <summary>${esc(config.title || 'Proposed controls')} (${n})<span class="tag">Proposed, not created yet</span></summary>
          ${config.lead ? `<div class="lead">${esc(config.lead)}</div>` : ''}
          <ul>${rows}</ul>
        </details></ha-card>`;
    }
    set hass(h) { this._hass = h; }
    getCardSize() { return 1; }
  }

  if (!customElements.get('ham-home-card')) customElements.define('ham-home-card', HamHomeCard);
  if (!customElements.get('ham-proposed-card')) customElements.define('ham-proposed-card', HamProposedCard);
  window.customCards = window.customCards || [];
  window.customCards.push({ type: 'ham-home-card', name: 'HAM home floor plan (draft)', description: 'Whole-apartment plan with live device state.' });
  window.customCards.push({ type: 'ham-proposed-card', name: 'HAM proposed controls (draft)', description: 'Dashed placeholder for helpers that do not exist yet.' });
})();
